"use strict";

const fs = require("node:fs");
const path = require("node:path");

const projectRoot = path.resolve(__dirname, "../..");
const assetsRoot = path.join(projectRoot, "public/assets/js");
const cssRoot = path.join(projectRoot, "public/assets/css");
const publicAssetsRoot = path.join(projectRoot, "public/assets");

function read(relativePath) {
  const absolutePath = path.join(assetsRoot, relativePath);
  return `/* --- ${relativePath} --- */\n${fs.readFileSync(absolutePath, "utf8").trim()}\n`;
}

function writeBundle(outputPath, sources) {
  const contents = [
    "/* This file is generated by src/scripts/buildClientBundles.js. */",
    "/* Edit the source modules listed below, then run npm run build:client. */",
    ...sources.map(read),
    "",
  ].join("\n\n");

  const absoluteOutputPath = path.join(assetsRoot, outputPath);
  fs.mkdirSync(path.dirname(absoluteOutputPath), { recursive: true });
  fs.writeFileSync(absoluteOutputPath, contents);
}

function resolveCssAsset(sourcePath, assetPath) {
  if (/^(?:[a-z]+:|\/|#)/i.test(assetPath)) {
    return assetPath;
  }

  const absoluteAssetPath = path.resolve(cssRoot, path.dirname(sourcePath), assetPath);
  if (!absoluteAssetPath.startsWith(`${publicAssetsRoot}${path.sep}`)) {
    return assetPath;
  }

  return `/assets/${path.relative(publicAssetsRoot, absoluteAssetPath).split(path.sep).join("/")}`;
}

function readCss(relativePath, stack = []) {
  if (stack.includes(relativePath)) {
    throw new Error(`Circular CSS import: ${[...stack, relativePath].join(" -> ")}`);
  }

  const source = fs.readFileSync(path.join(cssRoot, relativePath), "utf8");
  const withoutImports = source.replace(
    /@import\s+(?:url\()?\s*["']([^"']+)["']\s*\)?\s*;?/g,
    (_, importedPath) => {
      const cleanPath = importedPath.split("?")[0];
      const resolvedPath = path
        .normalize(path.join(path.dirname(relativePath), cleanPath))
        .split(path.sep)
        .join("/");
      return readCss(resolvedPath, [...stack, relativePath]);
    }
  );

  return withoutImports.replace(
    /url\(\s*(["']?)([^"')]+)\1\s*\)/g,
    (match, quote, assetPath) => {
      const rewrittenPath = resolveCssAsset(relativePath, assetPath);
      return `url(${quote}${rewrittenPath}${quote})`;
    }
  );
}

function writeCssBundle(outputPath, sources) {
  const contents = [
    "/* This file is generated by src/scripts/buildClientBundles.js. */",
    "/* Edit the source stylesheets listed below, then run npm run build:client. */",
    ...sources.map((source) => `/* --- ${source} --- */\n${readCss(source).trim()}`),
    "",
  ].join("\n\n");

  const absoluteOutputPath = path.join(cssRoot, outputPath);
  fs.mkdirSync(path.dirname(absoluteOutputPath), { recursive: true });
  fs.writeFileSync(absoluteOutputPath, contents);
}

const adminModules = [
  "admin/modules/00-state.js",
  "admin/modules/01-helpers.js",
  "admin/modules/02-ui-core.js",
  "admin/modules/03-dashboard.js",
  "admin/modules/04-employees.js",
  "admin/modules/05-points.js",
  "admin/modules/06-reports.js",
  "admin/modules/07-register.js",
  "admin/modules/08-settings-login.js",
  "admin/modules/09-init.js",
  "admin/modules/mobile-check.js",
  "admin/modules/settings.js",
];

// Os módulos administrativos são carregados pelo bootstrap público em ordem.
// Não os concatene: cada arquivo deve permanecer auditável e abaixo do limite.

for (const page of ["profile", "punch", "report"]) {
  writeBundle(`employee/${page}.js`, [
    "shared/loading.js",
    "employee/modules/shared.js",
    `employee/modules/${page}.js`,
  ]);
}

writeBundle("auth/login.js", ["shared/loading.js", "auth/modules/login.js"]);
writeBundle("auth/password-recovery.js", ["auth/modules/password-recovery.js"]);
writeBundle("auth/password.js", ["auth/modules/password.js"]);

// CSS é servido por manifestos @import em public/assets/css/bundles.
// Isso mantém a organização por responsabilidade sem recriar arquivos grandes.
console.log("Client JavaScript bundles built successfully; CSS uses public manifests.");
